import './ChipBar.css';

interface ChipBarProps {
  statuses: string[];
  selected: Set<string>;
  onSelectionChange: (next: Set<string>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleChipClick(status: string): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter by status">
      {statuses.map((status) => (
        <button
          key={status}
          type="button"
          className={`chip${selected.has(status) ? ' chip--pressed' : ''}`}
          aria-pressed={selected.has(status)}
          onClick={() => handleChipClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

