import { useState } from 'react';
import './ChipBar.css';

interface ChipBarProps {
  statuses: string[];
}

// Owns only visual pressed state; grid filtering is not wired.
export function ChipBar({ statuses }: ChipBarProps): JSX.Element {
  const [pressed, setPressed] = useState<Set<string>>(new Set());

  function handleChipClick(status: string): void {
    const next = new Set(pressed);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    setPressed(next);
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter by status">
      {statuses.map((status) => (
        <button
          key={status}
          type="button"
          className={`chip${pressed.has(status) ? ' chip--pressed' : ''}`}
          aria-pressed={pressed.has(status)}
          onClick={() => handleChipClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

